      "meta_description": "Learn about Pixelwave \u2014 the technology trends magazine with a bold voice, an independent editorial team, and a mission to make the future legible.",
      "sections": [
        {
          "id": "about-section-1",
          "type": "page_header",
          "intent": "Open the About page with a punchy mission statement that captures why Pixelwave exists and who it is for.",
          "eyebrow": "About Pixelwave",
          "headline": "We Cover the Future So You Don't Get Left Behind",
          "subheadline": "Pixelwave is an independent technology publication built for readers who want to understand what's actually happening \u2014 not just what went viral.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": []
