input.content:
/* ============================================
   PIXELWAVE — Y2K GLOSS DESIGN SYSTEM
   ============================================ */

:root {
  --chrome-slick: #C8D8E8;
  --bubblegum-burst: #FF6EB4;
  --laserdisc-lavender: #B8A0E8;
  --baby-screen-blue: #7EC8F0;
  --void-pixel: #1A1040;
  --glosspop-white: #F0F4FF;
  --starfield-magenta: #CC00AA;
  --foil-silver: #8FA8C0;

  --font-heading: 'Nunito', system-ui, -apple-system, sans-serif;
  --font-body: 'Archivo', system-ui, -apple-system, sans-serif;
  --font-accent: 'Montserrat', system-ui, -apple-system, sans-serif;

  --sidebar-width: 240px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.65;
  color: var(--void-pixel);
  background: var(--chrome-slick);
  overflow-x: hidden;
  min-height: 100vh;
}

a {
  color: var(--baby-screen-blue);
  text-decoration: none;
}

a:hover {
  color: var(--bubblegum-burst);
}

img, svg { max-width: 100%; display: block; }

/* ============================================
   APP LAYOUT — SIDEBAR + CONTENT
   ============================================ */

.app {
  display: flex;
  min-height: 100vh;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  width: var(--sidebar-width);
  background:
    linear-gradient(180deg, #D6E2EE 0%, var(--chrome-slick) 50%, #BCCEDF 100%);
  border-right: 1px solid rgba(184, 160, 232, 0.5);
  padding: 28px 24px;
  z-index: 50;
  display: flex;
  flex-direction: column;
}

.sidebar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--bubblegum-burst), var(--laserdisc-lavender), var(--baby-screen-blue));
  opacity: 0.85;
}

.brand {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 18px;
}

.brand__mark {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--bubblegum-burst);
  display: flex;
  align-items: center;
  gap: 6px;
}

.brand__mark svg { flex-shrink: 0; }

.brand__tag {
  font-family: var(--font-accent);
  font-size: 10px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--foil-silver);
}

.brand__rule {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--laserdisc-lavender), transparent);
  margin-top: 16px;
}

.nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 22px;
}

.nav__divider {
  margin: 14px 6px;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(180deg, var(--glosspop-white) 0%, var(--chrome-slick) 100%);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.6);
}

.nav__link {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--void-pixel);
  padding: 10px 12px;
  border-radius: 8px;
  transition: all 0.18s ease;
  display: flex;
  align-items: center;
  gap: 8px;
  font-weight: 600;
}

.nav__link::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--foil-silver);
  transition: background 0.18s ease;
}

.nav__link:hover {
  color: var(--laserdisc-lavender);
  background: rgba(184, 160, 232, 0.18);
}

.nav__link:hover::before {
  background: var(--laserdisc-lavender);
}

.nav__link.is-active {
  background: var(--bubblegum-burst);
  color: var(--void-pixel);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.5), 0 2px 8px rgba(255,110,180,0.35);
}

.nav__link.is-active::before {
  background: var(--void-pixel);
}

.sidebar__footer {
  margin-top: auto;
  padding-top: 24px;
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--foil-silver);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sidebar__pill {
  align-self: flex-start;
  padding: 4px 10px;
  background: var(--glosspop-white);
  border-radius: 999px;
  border: 1px solid var(--laserdisc-lavender);
  color: var(--void-pixel);
}

/* Main content */
.content {
  margin-left: var(--sidebar-width);
  flex: 1;
  min-width: 0;
}

/* ============================================
   COMMON SECTION STYLES
   ============================================ */

.section {
  position: relative;
}

.eyebrow {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--starfield-magenta);
  font-weight: 600;
  display: inline-flex;
  align-items: center;
  gap: 10px;
}

.eyebrow--rule::before {
  content: '';
  display: inline-block;
  width: 2px;
  height: 12px;
  background: var(--starfield-magenta);
}

.eyebrow--pill {
  background: rgba(255,110,180,0.15);
  border: 1px solid var(--bubblegum-burst);
  color: var(--bubblegum-burst);
  padding: 5px 12px;
  border-radius: 999px;
}

.eyebrow--gloss-pill {
  position: relative;
  padding: 6px 14px 6px 14px;
  background: linear-gradient(180deg, var(--starfield-magenta), #b3008f);
  color: var(--glosspop-white);
  border-radius: 999px;
  overflow: hidden;
}

.eyebrow--gloss-pill::after {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; height: 50%;
  background: linear-gradient(180deg, rgba(255,255,255,0.5), rgba(255,255,255,0));
  border-top-left-radius: 999px;
  border-top-right-radius: 999px;
  pointer-events: none;
}

.eyebrow--marker::before {
  content: '';
  display: inline-block;
  width: 32px;
  height: 6px;
  background: var(--laserdisc-lavender);
  border-radius: 999px;
}

.headline {
  font-family: var(--font-heading);
  color: var(--void-pixel);
  letter-spacing: -0.02em;
  line-height: 1.1;
  font-weight: 900;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 13px 28px;
  border-radius: 999px;
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.btn--primary {
  background: var(--bubblegum-burst);
  color: var(--void-pixel);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.6), 0 4px 14px rgba(255,110,180,0.35);
}

.btn--primary::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; height: 50%;
  background: linear-gradient(180deg, rgba(255,255,255,0.4), rgba(255,255,255,0));
  pointer-events: none;
}

.btn--primary:hover {
  background: var(--starfield-magenta);
  color: var(--glosspop-white);
  box-shadow: 0 0 24px rgba(204,0,170,0.55), inset 0 1px 0 rgba(255,255,255,0.4);
  transform: translateY(-1px);
}

.btn--ghost {
  background: transparent;
  color: var(--laserdisc-lavender);
  border: 2px solid var(--laserdisc-lavender);
}

.btn--ghost:hover {
  background: var(--laserdisc-lavender);
  color: var(--void-pixel);
}

.btn--invert {
  background: var(--glosspop-white);
  color: var(--bubblegum-burst);
}

.btn--invert:hover {
  background: var(--laserdisc-lavender);
  color: var(--glosspop-white);
}

.btn--dark {
  background: var(--void-pixel);
  color: var(--glosspop-white);
}

.btn--dark:hover {
  background: var(--starfield-magenta);
}

.text-link {
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 15px;
  color: var(--baby-screen-blue);
  text-decoration: underline;
  text-decoration-color: var(--baby-screen-blue);
  text-decoration-thickness: 2px;
  text-underline-offset: 3px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.text-link__chev {
  color: var(--bubblegum-burst);
  font-weight: 800;
  text-decoration: none;
  display: inline-block;
}

/* ============================================
   HOME PAGE
   ============================================ */

[data-page-slug="home"] [data-section-type="hero"] {
  background: var(--void-pixel);
  padding: 80px 0 64px 48px;
  position: relative;
  overflow: hidden;
}

[data-page-slug="home"] [data-section-type="hero"] .hero__bg-grid {
  position: absolute;
  inset: 0;
  background-image:
    radial-gradient(circle at 80% 20%, rgba(126,200,240,0.18), transparent 50%),
    radial-gradient(circle at 20% 80%, rgba(184,160,232,0.12), transparent 60%);
  pointer-events: none;
}

.hero {
  position: relative;
  z-index: 2;
  max-width: 100%;
}

.hero__eyebrow {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--starfield-magenta);
  font-weight: 700;
  position: relative;
  padding-left: 12px;
  display: inline-block;
}

.hero__eyebrow::before {
  content: '';
  position: absolute;
  left: 0;
  top: 2px;
  width: 2px;
  height: 12px;
  background: var(--starfield-magenta);
}

.hero__headline-stack {
  position: relative;
  margin-top: 18px;
}

.hero__line1 {
  font-family: var(--font-heading);
  font-weight: 900;
  font-size: clamp(36px, 5vw, 52px);
  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: var(--glosspop-white);
  line-height: 1;
}

.hero__line2-wrap {
  position: relative;
  display: block;
  white-space: nowrap;
  margin-top: 6px;
  line-height: 1;
}

.hero__line2 {
  font-family: var(--font-heading);
  font-weight: 900;
