  letter-spacing: -0.03em;
  text-transform: uppercase;
  color: var(--glosspop-white);
  line-height: 1;
}

.hero__line2-wrap {
  position: relative;
  display: block;
  white-space: nowrap;
  margin-top: 6px;
  line-height: 1;
}

.hero__line2 {
