}

.hero__ctas {
  margin-top: 32px;
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.section__divider-rule {
  height: 1px;
  background: var(--laserdisc-lavender);
  opacity: 0.4;
  margin: 0;
}

/* Article list (top stories) */
[data-page-slug="home"] [data-section-type="article_list"] {
  background: var(--glosspop-white);
  padding: 0 0 64px 0;
}

.masthead-strip {
  background: var(--chrome-slick);
  padding: 12px 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  height: 44px;
  margin-bottom: 32px;
}

.masthead-strip__eyebrow {
  font-family: var(--font-accent);
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--void-pixel);
  font-weight: 700;
}

.masthead-strip__title {
  font-family: var(--font-heading);
  font-weight: 800;
  font-size: 18px;
  color: var(--void-pixel);
  text-align: right;
}

.cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  padding: 0 48px;
}

.card {
  position: relative;
  background: var(--chrome-slick);
  border: 1.5px solid var(--laserdisc-lavender);
  border-radius: 12px;
  padding: 24px;
