}

.chip {
  display: inline-flex;
  font-family: var(--font-accent);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--baby-screen-blue);
  color: var(--void-pixel);
  align-self: flex-start;
}

.chip--lavender { background: var(--laserdisc-lavender); }

.chip--pink {
  background: var(--bubblegum-burst);
  color: var(--void-pixel);
}

.sticker {
  position: absolute;
  font-family: var(--font-accent);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  background: var(--bubblegum-burst);
  color: var(--void-pixel);
  padding: 6px 12px;
  border-radius: 999px;
  top: -10px;
  left: 16px;
  transform: rotate(-4deg);
  box-shadow: 0 2px 8px rgba(255,110,180,0.4), inset 0 1px 0 rgba(255,255,255,0.5);
  z-index: 3;
}

.starburst {
  position: absolute;
  width: 56px;
  height: 56px;
  top: -16px;
  right: -12px;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 3;
  filter: drop-shadow(0 2px 8px rgba(204,0,170,0.4));
}

.starburst__label {
  position: absolute;
  font-family: var(--font-accent);
  font-size: 8px;
  font-weight: 800;
  color: var(--glosspop-white);
  letter-spacing: 0.08em;
  z-index: 4;
}

.section__cta {
  padding: 32px 48px 0 48px;
  text-align: right;
}

/* Newsletter CTA */
[data-page-slug="home"] [data-section-type="cta"] {
  background: var(--bubblegum-burst);
  padding: 72px 48px;
