  z-index: 2;
}

.subscribe-form__btn:hover {
  background: var(--starfield-magenta);
}

.cta-block__disclaimer {
  margin-top: 14px;
  font-family: var(--font-accent);
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(26,16,64,0.5);
